
# Diffie-Hellman Key Exchange Algorithm

# Public parameters
p = 23  # Prime number
g = 5   # Primitive root

print("===== DIFFIE-HELLMAN KEY EXCHANGE =====")

# Private keys chosen by Alice and Bob
a = int(input("Enter Alice's private key: "))
b = int(input("Enter Bob's private key: "))

# Public keys generated by Alice and Bob
A = pow(g, a, p)
B = pow(g, b, p)

print("\nPublic parameters:")
print("Prime number (p):", p)
print("Primitive root (g):", g)

print("\nAlice's public key:", A)
print("Bob's public key:", B)

# Both parties independently calculate the shared secret
alice_key = pow(B, a, p)
bob_key = pow(A, b, p)

print("\nAlice's shared secret key:", alice_key)
print("Bob's shared secret key:", bob_key)

# Verify that both keys match
if alice_key == bob_key:
    print("\nKey Exchange Successful!")
    print("Both parties have generated the same shared secret.")
else:
    print("\nKey Exchange Failed!")
